function perfectpixel_quick_edit_field() {
	echo '<br class="clear"><label class="alignleft"><span class="title">' . esc_html( '{{quick_edit_label}}' ) . '</span><span class="input-text-wrap"><input type="text" name="perfectpixel_quick_edit_field" class="text" value=""></span></label>';
}

// The current value, hidden in the "name" column, for the script to read.
function perfectpixel_quick_edit_field_data( $column, $post_id ) {
	if ( 'name' === $column ) {
		echo '<div class="hidden perfectpixel-qe-value">' . esc_html( (string) get_post_meta( $post_id, sanitize_key( '{{quick_edit_meta_key}}' ), true ) ) . '</div>';
	}
}

function perfectpixel_quick_edit_field_save( $product ) {
	if ( isset( $_REQUEST['perfectpixel_quick_edit_field'] ) && current_user_can( 'edit_product', $product->get_id() ) ) {
		$product->update_meta_data( sanitize_key( '{{quick_edit_meta_key}}' ), sanitize_text_field( wp_unslash( $_REQUEST['perfectpixel_quick_edit_field'] ) ) );
		$product->save_meta_data();
	}
}

function perfectpixel_quick_edit_field_script() {
	if ( 'product' !== get_current_screen()->post_type ) {
		return;
	}
	?>
	<script>
	jQuery( function ( $ ) {
		$( '#the-list' ).on( 'click', '.editinline', function () {
			var row   = $( this ).closest( 'tr' );
			var value = row.find( '.perfectpixel-qe-value' ).text();
			setTimeout( function () {
				$( '.inline-edit-row input[name="perfectpixel_quick_edit_field"]' ).val( value );
			} );
		} );
	} );
	</script>
	<?php
}
